#' Match Flights to Traffic Management Rules (RAD/AWK)
#'
#' @description
#' This function identifies which traffic management rules apply to a given set of flights.
#' It utilizes an inverted index approach to perform high-speed matching without
#' creating a Cartesian product, effectively handling aviation wildcard formats
#' (e.g., "LF..", "E...").
#'
#' @param flights A \code{data.table} containing flight data. While this is typically
#' an \code{exp2} dataset generated by \code{read_exp2()}, any flight dataset
#' with departure and arrival ICAO columns is compatible.
#' @param rules A \code{data.table} containing the constraint rules. This is
#' typically an \code{awk} dataset generated by \code{read_awk()}.
#' @param adep_col Character. The name of the departure airport column in
#' the \code{flights} dataset. Default is \code{"adep"}.
#' @param ades_col Character. The name of the arrival airport column in
#' the \code{flights} dataset. Default is \code{"ades"}.
#' @param dep_rule_col Character. The name of the departure constraint column
#' in the \code{rules} dataset. Default is \code{"condition_dep"}.
#' @param arr_rule_col Character. The name of the arrival constraint column
#' in the \code{rules} dataset. Default is \code{"condition_arr"}.
#' @param rule_id_col Character. The unique identifier column for rules.
#' Default is \code{"rule_id"}.
#'
#' @details
#' The function matches constraints with city-pairs info.
#' It handles "Match All" cases where
#' a constraint column is \code{NA}, empty, or contains \code{"*"}.
#'
#' @return The original \code{flights} dataset with an additional list-column
#' \code{hit_rules} containing the IDs of all applicable rules for each flight.
#'
#' @export
#' @import data.table
match_flight_rules <- function(flights,
                               rules,
                               adep_col = "adep",
                               ades_col = "ades",
                               dep_rule_col = "condition_dep",
                               arr_rule_col = "condition_arr",
                               rule_id_col = "rule_id") {

  # 1. Internal Working Copies
  # We copy rules to protect the original awk object
  r_work <- copy(rules)

  # Standardize rule columns internally
  setnames(r_work, c(dep_rule_col, arr_rule_col, rule_id_col), c("R_DEP", "R_ARR", "R_ID"))

  # 2. Pre-process Rules
  r_work[, R_ID := as.integer(R_ID)]
  r_work[, R_DEP := trimws(as.character(R_DEP))]
  r_work[, R_ARR := trimws(as.character(R_ARR))]

  # Identify "Any Airport" rules (NAs or wildcards)
  r_work[, dep_any := is.na(R_DEP) | R_DEP == "" | R_DEP == "*"]
  r_work[, arr_any := is.na(R_ARR) | R_ARR == "" | R_ARR == "*"]

  # 3. Build Inverted Index
  # Split pipe-separated strings into search tokens
  dep_idx <- r_work[dep_any == FALSE, .(token = unlist(strsplit(R_DEP, "\\|"))), by = R_ID]
  arr_idx <- r_work[arr_any == FALSE, .(token = unlist(strsplit(R_ARR, "\\|"))), by = R_ID]

  setkey(dep_idx, token)
  setkey(arr_idx, token)

  # 4. Generate Flight Search Keys
  # Map flight row index to its prefix variations
  f_map <- flights[, .(
    f_idx = .I,
    dep_token = list(c(get(adep_col), paste0(substr(get(adep_col), 1, 2), ".."), paste0(substr(get(adep_col), 1, 1), "..."))),
    arr_token = list(c(get(ades_col), paste0(substr(get(ades_col), 1, 2), ".."), paste0(substr(get(ades_col), 1, 1), "...")))
  ), by = 1:nrow(flights)]

  fl_keys_dep <- f_map[, .(token = unlist(dep_token)), by = f_idx]
  fl_keys_arr <- f_map[, .(token = unlist(arr_token)), by = f_idx]

  # 5. Execute Binary Joins
  dep_hits <- dep_idx[fl_keys_dep, on = "token", nomatch = 0, allow.cartesian = TRUE][, .(R_ID, f_idx)]
  arr_hits <- arr_idx[fl_keys_arr, on = "token", nomatch = 0, allow.cartesian = TRUE][, .(R_ID, f_idx)]

  # 6. Resolve Logical Combinations
  # Specific Dep & Specific Arr
  res_both <- merge(dep_hits, arr_hits, by = c("f_idx", "R_ID"), allow.cartesian = TRUE)

  # Specific Dep, Any Arr
  res_dep_only <- dep_hits[R_ID %in% r_work[dep_any == FALSE & arr_any == TRUE, R_ID]]

  # Any Dep, Specific Arr
  res_arr_only <- arr_hits[R_ID %in% r_work[dep_any == TRUE & arr_any == FALSE, R_ID]]

  # Global Rules (Any/Any)
  global_ids <- r_work[dep_any == TRUE & arr_any == TRUE, R_ID]
  res_global <- if(length(global_ids) > 0) CJ(f_idx = f_map$f_idx, R_ID = global_ids) else data.table()

  # 7. Aggregate Hits
  all_hits <- rbindlist(list(res_both, res_dep_only, res_arr_only, res_global), use.names = TRUE)
  final_matches <- unique(all_hits)[, .(hit_rules = list(as.integer(R_ID))), by = f_idx]

  # 8. Merge results back to original flight table
  # Use a copy of the flight table to avoid unintended side effects
  res_flights <- copy(flights)
  res_flights[, f_idx := .I]

  output <- final_matches[res_flights, on = "f_idx"]

  # Clean up: replace NA with empty integer vectors and remove temp index
  output[is.na(hit_rules), hit_rules := list(list(integer(0)))]
  output[, f_idx := NULL]

  return(output[])
}
